import XCTest
@testable import HorizontalNative

/// Texts drawn as Horizon EDA draws them, against Horizon's own output.
///
/// `reference` is what Horizon's `TextRenderer::render` (src/util/
/// text_renderer.cpp, built from Horizon's sources) drew for each case, with
/// the steps its canvas takes before it: `transform.accumulate(placement)`
/// for a package or decal, `transform.invert_angle()` when that is flipped,
/// and `rev` the layer's `reverse`. A text on a reverse layer — the bottom
/// copper, mask, silkscreen, assembly and notes — is drawn mirrored as seen
/// from above, which is how a bottom silkscreen reads the right way round
/// on the finished board.
///
/// Each line is `name;text;has parent;parent x;y;angle;flip;text x;y;angle;
/// mirror;rev;origin;allow upside down;size;width;probe x;y;segments`. The
/// probe is where the parent's placement puts the point (1 mm, 0.25 mm).
final class HorizonTextRenderingReferenceTests: XCTestCase {
    private struct Case {
        var name: String
        var text: String
        var parent: HorizontalPlacementTransform?
        var child: HorizontalPlacementTransform
        var reverse: Bool
        var origin: HorizontalTextOrigin
        var allowUpsideDown: Bool
        var size: Double
        var width: Double
        var probe: HorizontalPoint
        var segments: [[Double]]
    }

    /// Horizon draws with 32-bit floats, good to a few nanometres at these
    /// coordinates; the strokes compared are tens of micrometres long.
    private let tolerance = 8.0

    private static func cases() -> [Case] {
        reference.split(separator: "\n").map { line in
            let fields = line.split(separator: ";", omittingEmptySubsequences: false).map(String.init)
            func number(_ index: Int) -> Double { Double(fields[index]) ?? .nan }
            func flag(_ index: Int) -> Bool { fields[index] == "1" }
            let origins: [HorizontalTextOrigin] = [.baseline, .center, .bottom]
            return Case(
                name: fields[0],
                text: fields[1].replacingOccurrences(of: "\\n", with: "\n"),
                parent: flag(2)
                    ? HorizontalPlacementTransform(
                        shift: HorizontalPoint(x: number(3), y: number(4)), angle: Int(number(5)), mirrored: flag(6))
                    : nil,
                child: HorizontalPlacementTransform(
                    shift: HorizontalPoint(x: number(7), y: number(8)), angle: Int(number(9)), mirrored: flag(10)),
                reverse: flag(11),
                origin: origins[Int(number(12))],
                allowUpsideDown: flag(13),
                size: number(14),
                width: number(15),
                probe: HorizontalPoint(x: number(16), y: number(17)),
                segments: fields[18].split(separator: ",").map { $0.split(separator: " ").map { Double($0) ?? .nan } }
            )
        }
    }

    /// The text of a case as the board's loader makes it: a board's own text
    /// in the board's frame, a package's or decal's in its placement's, on
    /// the silkscreen of the side it is on (or, for the cases Horizon does
    /// not reverse, the bottom package layer).
    private func text(for item: Case) -> HorizontalText {
        let placed = (item.parent ?? .identity).accumulatedBoardText(with: item.child)
        let layer: Int
        if item.reverse {
            layer = HorizontalBoardLayers.bottomSilkscreen
        } else if item.parent?.mirrored == true {
            layer = HorizontalBoardLayers.bottomPackage
        } else {
            layer = HorizontalBoardLayers.topSilkscreen
        }
        return HorizontalText(
            id: item.name,
            text: item.text,
            position: placed.shift,
            size: item.size,
            layer: layer,
            angle: placed.angle,
            mirrored: placed.mirrored,
            width: item.width,
            origin: item.origin,
            allowUpsideDown: item.allowUpsideDown
        )
    }

    /// A stroke with its ends in one order, so two drawings of the same
    /// strokes compare however each runs them.
    private func ordered(_ s: [Double]) -> [Double] {
        let a = [s[0], s[1]], b = [s[2], s[3]]
        return a.lexicographicallyPrecedes(b) ? a + b : b + a
    }

    /// Every stroke drawn is one of Horizon's and every one of Horizon's is
    /// drawn, to the tolerance, in whatever order each lists them.
    private func assertDrawsAsHorizon(_ text: HorizontalText, _ item: Case, file: StaticString = #filePath, line: UInt = #line) {
        let drawn = HorizontalOutlineTextRenderer.outlineSegments(for: text).map { ordered([$0.0.x, $0.0.y, $0.1.x, $0.1.y]) }
        let expected = item.segments.map(ordered)
        XCTAssertEqual(drawn.count, expected.count, "\(item.name): stroke count", file: file, line: line)
        func distance(_ a: [Double], _ b: [Double]) -> Double {
            // Ends within a nanometre of each other can order either way.
            let swapped = [b[2], b[3], b[0], b[1]]
            return min(zip(a, b).map { abs($0 - $1) }.max() ?? .infinity, zip(a, swapped).map { abs($0 - $1) }.max() ?? .infinity)
        }
        for stroke in drawn {
            let nearest = expected.map { distance(stroke, $0) }.min() ?? .infinity
            if nearest > tolerance {
                XCTFail("\(item.name): drew \(stroke), which is none of Horizon's strokes (nearest is \(nearest) nm off)", file: file, line: line)
                return
            }
        }
        for stroke in expected {
            let nearest = drawn.map { distance(stroke, $0) }.min() ?? .infinity
            if nearest > tolerance {
                XCTFail("\(item.name): Horizon draws \(stroke), which was not drawn (nearest is \(nearest) nm off)", file: file, line: line)
                return
            }
        }
    }

    func testEveryReferenceCaseDrawsAsHorizonDrawsIt() {
        let cases = Self.cases()
        XCTAssertEqual(cases.count, 85)
        for item in cases {
            assertDrawsAsHorizon(text(for: item), item)
        }
    }

    func testAPackageOrDecalPlacementPutsItsGeometryWhereHorizonDoes() {
        for item in Self.cases() {
            guard let parent = item.parent else { continue }
            let probe = parent.applying(to: HorizontalPoint(x: 1_000_000, y: 250_000))
            XCTAssertEqual(probe.x, item.probe.x, accuracy: 1, item.name)
            XCTAssertEqual(probe.y, item.probe.y, accuracy: 1, item.name)
        }
    }

    func testATextOnAReverseLayerIsTheMirrorImageOfTheSameTextOnTop() {
        // One angle and one mirror flag say the same on either side: moving a
        // text to the bottom silkscreen flips its glyphs top to bottom about
        // its baseline's direction, which seen from below is the text upright.
        for angle in [0, 16_384, 32_768, 49_152, 8_192] {
            let top = HorizontalText(
                id: "t", text: "F", position: HorizontalPoint(x: 500, y: -300), size: 1_000_000,
                layer: HorizontalBoardLayers.topSilkscreen, angle: angle, allowUpsideDown: true)
            var bottom = top
            bottom.layer = HorizontalBoardLayers.bottomSilkscreen
            XCTAssertTrue(bottom.readsFromBelow)
            XCTAssertFalse(top.readsFromBelow)
            let radians = Double(angle) / 65_536 * 2 * .pi
            // Reflect a point across the line through the anchor along the
            // text's direction.
            func reflected(_ point: HorizontalPoint) -> HorizontalPoint {
                let dx = point.x - top.position.x, dy = point.y - top.position.y
                let along = dx * cos(radians) + dy * sin(radians)
                let across = -dx * sin(radians) + dy * cos(radians)
                return HorizontalPoint(
                    x: top.position.x + along * cos(radians) + across * sin(radians),
                    y: top.position.y + along * sin(radians) - across * cos(radians))
            }
            let expected = HorizontalOutlineTextRenderer.outlineSegments(for: top).map { (reflected($0.0), reflected($0.1)) }
            let drawn = HorizontalOutlineTextRenderer.outlineSegments(for: bottom)
            XCTAssertEqual(drawn.count, expected.count)
            for (mine, theirs) in zip(drawn, expected) {
                XCTAssertEqual(mine.0.x, theirs.0.x, accuracy: 1e-3, "angle \(angle)")
                XCTAssertEqual(mine.0.y, theirs.0.y, accuracy: 1e-3, "angle \(angle)")
                XCTAssertEqual(mine.1.x, theirs.1.x, accuracy: 1e-3, "angle \(angle)")
                XCTAssertEqual(mine.1.y, theirs.1.y, accuracy: 1e-3, "angle \(angle)")
            }
        }
    }

    func testOnlyTheLayersHorizonReversesAreReadFromBelow() {
        let reversed = HorizontalBoardLayers.all.filter(HorizontalBoardLayers.isReverse)
        XCTAssertEqual(Set(reversed), [
            HorizontalBoardLayers.bottomCopper,
            HorizontalBoardLayers.bottomMask,
            HorizontalBoardLayers.bottomSilkscreen,
            HorizontalBoardLayers.bottomAssembly,
            HorizontalBoardLayers.bottomNotes,
        ])
        XCTAssertFalse(HorizontalBoardLayers.isReverse(HorizontalBoardLayers.in1Copper))
        XCTAssertFalse(HorizontalText(id: "s", text: "x", position: .zero, size: 1, layer: nil).readsFromBelow)
    }

    func testAFlippedDecalIsTurnedByItsAngleAsHorizonTurnsIt() throws {
        // A logo flipped, at 270 degrees and half size. Horizon puts its
        // point (2 mm, 0.5 mm) at (41.75 mm, 1.35 mm); with the angle
        // inverted a second time it was half a turn round, at (41.25 mm,
        // -0.65 mm).
        let decalJSON: JSONDictionary = [
            "name": "Logo",
            "polygons": [
                "11111111-1111-1111-1111-111111111111": [
                    "layer": HorizontalBoardLayers.topSilkscreen,
                    "vertices": [
                        ["position": [2_000_000, 500_000], "type": "line", "arc_center": [0, 0], "arc_reverse": false],
                        ["position": [4_000_000, 500_000], "type": "line", "arc_center": [0, 0], "arc_reverse": false],
                        ["position": [4_000_000, 1_500_000], "type": "line", "arc_center": [0, 0], "arc_reverse": false],
                    ] as [JSONDictionary],
                ] as JSONDictionary,
            ] as JSONDictionary,
            "texts": [
                "22222222-2222-2222-2222-222222222222": [
                    "text": "F\nL",
                    "layer": HorizontalBoardLayers.topSilkscreen,
                    "size": 2_000_000,
                    "width": 200_000,
                    "origin": "center",
                    "font": "simplex",
                    "placement": ["shift": [1_400_000, 600_000], "angle": 0, "mirror": false] as JSONDictionary,
                ] as JSONDictionary,
            ] as JSONDictionary,
        ]
        let entry = HorizontalBoardDecal.fileEntry(
            decalID: "dddddddd-1111-4222-8333-444444444444",
            position: HorizontalPoint(x: 41_500_000, y: 350_000),
            angle: 49_152,
            flip: true,
            scale: 0.5
        )
        let decal = try XCTUnwrap(HorizontalBoard.boardDecal(id: "logo", entry: entry, decalJSON: decalJSON, nInnerLayers: 4))

        let polygon = try XCTUnwrap(decal.polygons.first)
        XCTAssertEqual(polygon.layer, HorizontalBoardLayers.bottomSilkscreen)
        let first = try XCTUnwrap(polygon.vertices.first)
        XCTAssertEqual(first.x, 41_750_000, accuracy: 1)
        XCTAssertEqual(first.y, 1_350_000, accuracy: 1)

        // Its text, half size, is the reference's text of a parent flipped
        // at 270 degrees, moved to where this decal lies.
        let text = try XCTUnwrap(decal.texts.first)
        XCTAssertEqual(text.layer, HorizontalBoardLayers.bottomSilkscreen)
        let item = try XCTUnwrap(Self.cases().first { $0.name == "parent a49152 flip1 text a0 m0" })
        let parent = try XCTUnwrap(item.parent)
        var moved = text
        moved.position = HorizontalPoint(
            x: text.position.x - 41_500_000 + parent.shift.x,
            y: text.position.y - 350_000 + parent.shift.y)
        assertDrawsAsHorizon(moved, item)
    }

